<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');csrf_check();$kid=(int)($_POST['id_kegiatan']??0);$data=$_SESSION['kwitansi_import']??null;if(!$data||(int)$data['id_kegiatan']!==$kid||$data['errors']||!$data['rows']){flash('danger','Preview tidak valid atau terdapat kesalahan.');redirect('/admin/kwitansi/excel.php?id='.$kid);}try{$pdo->beginTransaction();$sql='INSERT INTO kwitansi(id_progress,nominal,keperluan,nomor_surat_tugas,tanggal_surat_tugas,lama_perjalanan,berangkat,pulang,asal_penugasan,daerah_tujuan,bulan_pengajuan_kwitansi,dibuat_oleh) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE nominal=VALUES(nominal),keperluan=VALUES(keperluan),nomor_surat_tugas=VALUES(nomor_surat_tugas),tanggal_surat_tugas=VALUES(tanggal_surat_tugas),lama_perjalanan=VALUES(lama_perjalanan),berangkat=VALUES(berangkat),pulang=VALUES(pulang),asal_penugasan=VALUES(asal_penugasan),daerah_tujuan=VALUES(daerah_tujuan),bulan_pengajuan_kwitansi=VALUES(bulan_pengajuan_kwitansi),dibuat_oleh=VALUES(dibuat_oleh)';$s=$pdo->prepare($sql);foreach($data['rows'] as $r)$s->execute([$r['id_progress'],$r['nominal'],$r['keperluan'],$r['nomor_surat_tugas']?:null,$r['tanggal_surat_tugas'],$r['lama_perjalanan']?:null,$r['berangkat'],$r['pulang'],$r['asal_penugasan']?:null,$r['daerah_tujuan']?:null,$r['bulan_pengajuan_kwitansi'],current_user()['id_user']]);$count=count($data['rows']);$pdo->commit();unset($_SESSION['kwitansi_import']);flash('success',"Data administrasi kwitansi berhasil disimpan/diperbarui: {$count} baris.");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Import gagal: '.$e->getMessage());}redirect('/admin/kwitansi/index.php?id='.$kid);
